                <SearchPageHeader
                    queryJSON={queryJSON}
                    hash={hash}
                />
                <SearchStatusBar
                    type={type}
                    status={status}
                    resetOffset={resetOffset}
                />
                <EmptySearchView type={type} />
            </>
